create temp table _b on commit drop as select * from jsonb_to_recordset($j$[{"sku":"MIM-PESC01","slug":"chaveiro-porta-escovinha-de-cilios","nome":"Chaveiro Porta Escovinha de Cílios","preco":15.9,"a_partir":true,"selo":"9 modelos","tags":["Amiga ou amigo","Colega de trabalho","Lembrança de festa","Sai em lote"],"descricao":"✨ Um tubinho com tampa que guarda a escovinha de cílios ou de sobrancelha limpa dentro da bolsa. Presente certo para a cliente de lash e design de sobrancelha.\n\nTem em nove modelos: Borboletas, Flores, Coração, Coroa, Lábios, Cílios, Bolhas, Borboletas com espelho e nome, e Com o logo do salão. No modelo com nome e no modelo com logo, a gente confirma a grafia e a arte com você no WhatsApp antes de produzir.\n\n📦 O QUE VEM NO PEDIDO\n1 porta escovinha no modelo e na cor escolhidos\n1 corrente com argola de chaveiro\nNo modelo com espelho, 1 espelhinho redondo no pingente de coração\nA escovinha e o pingente de borboleta das fotos não acompanham o produto\n\n📏 FICHA TÉCNICA\nMaterial: PLA\nPeso: aproximadamente 13 a 20 g, conforme o modelo\nCores: Rosa, Rosa bebê, Roxo ametista, Azul bebê, Branco ou Preto\n\n💅 PARA O SEU SALÃO\nPara dar às clientes em data especial, aniversário ou fidelidade, monte um kit a partir de 10 peças e chame a gente no WhatsApp para combinar cores e quantidade.\n\n⏱️ PRAZO\nProduzido em 3 a 5 dias úteis depois do pagamento.\n\n🧼 CUIDADOS\nLimpar com pano seco.\nNão deixar ao sol direto ou dentro do carro. O PLA pode deformar em temperatura alta.\nNão é brinquedo. Não indicado para menores de 3 anos, porque tem peças pequenas.","ordem":72,"cores":["Rosa","Rosa bebê","Roxo ametista","Azul bebê","Branco","Preto"],"fotos":["assets/fotos/chaveiro-porta-escovinha-de-cilios-1.jpg","assets/fotos/chaveiro-porta-escovinha-de-cilios-2.jpg","assets/fotos/chaveiro-porta-escovinha-de-cilios-3.jpg"],"opcoes":[{"nome":"Borboletas","preco":15.9},{"nome":"Flores","preco":15.9},{"nome":"Coração","preco":15.9},{"nome":"Coroa","preco":15.9