  as x(sku text, slug text, nome text, preco numeric, a_partir boolean, selo text, tags text[], descricao text, ordem int, cores text[], fotos text[], opcoes jsonb);
insert into produtos (slug, sku, nome, categoria_id, preco, descricao, publicado, ordem, tags, selo, a_partir, grupos)
  select b.slug, b.sku, b.nome, c.id, b.preco, b.descricao, true, b.ordem, b.tags, b.selo, b.a_partir, '{}'::text[]
  from _b b cross join categorias c where c.slug = 'brindes-para-salao' on conflict (slug) do nothing;
insert into produto_fotos (produto_id, caminho, tipo, ordem)
  select p.id, f.caminho, 'criador', f.n - 1 from _b b join produtos p on p.slug = b.slug, unnest(b.fotos) with ordinality f(caminho, n)
  where not exists (select 1 from produto_fotos x where x.produto_id = p.id);
insert into variacoes (produto_id, cor, ordem)
  select p.id, v.cor, v.n - 1 from _b b join produtos p on p.slug = b.slug, unnest(b.cores) with ordinality v(cor, n)
  where not exists (select 1 from variacoes x where x.produto_id = p.id);
insert into produto_opcoes (produto_id, nome, preco, ordem)
  select p.id, o.v->>'nome', (o.v->>'preco')::numeric, o.n - 1 from _b b join produtos p on p.slug = b.slug, jsonb_array_elements(b.opcoes) with ordinality o(v, n)
  where not exists (select 1 from produto_opcoes x where x.produto_id = p.id);
